files.content:
:root {
  --bg: #1a1c2c;
  --card: #2c2e4a;
  --text: #f4f4f4;
  --accent: #ffcd75;
  --accent-dark: #c9a050;
  --border: #5d5d8a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--bg);
  background-image: linear-gradient(45deg, #22243a 25%, transparent 25%, transparent 75%, #22243a 75%),
                    linear-gradient(45deg, #22243a 25%, transparent 25%, transparent 75%, #22243a 75%);
  background-size: 16px 16px;
  background-position: 0 0, 8px 8px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 #0f0f1a;
  padding: 32px 24px;
  max-width: 400px;
  width: 100%;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 #000;
  margin-bottom: 4px;
}

.mode-label {
  font-size: 1.125rem;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.timer {
  font-size: 4.5rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: 4px;
  color: var(--text);
  text-shadow: 3px 3px 0 #000;
  padding: 8px 0;
  line-height: 1;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 12px 20px;
  background: var(--border);
  color: var(--text);
  border: 3px solid #0f0f1a;
  box-shadow: 4px 4px 0 #0f0f1a;
  cursor: pointer;
  transition: transform 0.05s, box-shadow 0.05s, background 0.15s;
  min-width: 100px;
}

.btn:hover {
  background: #7a7ab0;
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 #0f0f1a;
}

.btn.active {
  background: var(--accent);
  color: #1a1c2c;
}

.mode-switch {
  display: flex;
  gap: 8px;
  justify-content: center;
  flex-wrap: wrap;
  margin-top: 8px;
}

.mode-btn {
  font-size: 0.875rem;
  padding: 8px 12px;
  min-width: auto;
  flex: 1 1 0;
}

@media (max-width: 400px) {
  .timer {
    font-size: 3.5rem;
  }
  .btn {
    min-width: 80px;
    padding: 10px 14px;
  }
}

const WORK_TIME = 25 * 60;
const BREAK_TIME = 5 * 60;

const timerDisplay = document.getElementById('timerDisplay');
const modeLabel = document.getElementById('modeLabel');
const startPauseBtn = document.getElementById('startPauseBtn');
const resetBtn = document.getElementById('resetBtn');
const workModeBtn = document.getElementById('workModeBtn');
const breakModeBtn = document.getElementById('breakModeBtn');

let timeLeft = WORK_TIME;
let isRunning = false;
let timerInterval = null;
let currentMode = 'work';

function formatTime(seconds) {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

function updateDisplay() {
  timerDisplay.textContent = formatTime(timeLeft);
}

function setMode(mode) {
  currentMode = mode;
  timeLeft = mode === 'work' ? WORK_TIME : BREAK_TIME;
  modeLabel.textContent = mode === 'work' ? 'Work' : 'Break';
  workModeBtn.classList.toggle('active', mode === 'work');
  breakModeBtn.classList.toggle('active', mode === 'break');
  workModeBtn.setAttribute('aria-pressed', mode === 'work');
  breakModeBtn.setAttribute('aria-pressed', mode === 'break');
  updateDisplay();
  if (isRunning) {
    pauseTimer();
  }
}

function startTimer() {
  if (isRunning) return;
  isRunning = true;
  startPauseBtn.textContent = 'Pause';
  startPauseBtn.setAttribute('aria-label', 'Pause timer');
  timerInterval = setInterval(() => {
    timeLeft--;
    updateDisplay();
    if (timeLeft <= 0) {
      clearInterval(timerInterval);
      timerInterval = null;
      isRunning = false;
      startPauseBtn.textContent = 'Start';
      startPauseBtn.setAttribute('aria-label', 'Start timer');
      if (currentMode === 'work') {
        setMode('break');
      } else {
        setMode('work');
      }
    }
  }, 1000);
}

function pauseTimer() {
  if (!isRunning) return;
  isRunning = false;
  clearInterval(timerInterval);
  timerInterval = null;
  startPauseBtn.textContent = 'Start';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
}

function toggleTimer() {
  if (isRunning) {
    pauseTimer();
  } else {
    startTimer();
  }
}

function resetTimer() {
  pauseTimer();
  timeLeft = currentMode === 'work' ? WORK_TIME : BREAK_TIME;
  updateDisplay();
}

startPauseBtn.addEventListener('click', toggleTimer);
resetBtn.addEventListener('click', resetTimer);
workModeBtn.addEventListener('click', () => setMode('work'));
breakModeBtn.addEventListener('click', () => setMode('break'));

updateDisplay();
